<?php
declare(strict_types=1);namespace App\Application\Payments\Adapters;
use App\Models\PaymentIntentRecord;use DomainException;use Illuminate\Support\Facades\Http;
final class ConfiguredJsonPaymentAdapter implements PaymentProviderAdapter{public function __construct(private string$name){}public function provider():string{return$this->name;}public function requestCustomerAuthorization(PaymentIntentRecord$i,string$r):ProviderInitiationResult{$endpoint=(string)config("payments.providers.{$this->name}.initiate_url");$token=(string)config("payments.providers.{$this->name}.api_token");if($endpoint===''||$token==='')throw new DomainException('Payment provider is not configured.');$response=Http::asJson()->acceptJson()->withToken($token)->withHeaders(['Idempotency-Key'=>$r,'X-Request-Id'=>$r])->timeout(15)->retry(2,250,throw:false)->post($endpoint,['amount'=>$i->amount_minor,'currency'=>$i->currency,'payer'=>$i->payer_phone_e164,'callback_url'=>route('payments.webhook',['provider'=>$this->name])]);if(!$response->successful())throw new DomainException('Provider authorization request failed.');$reference=(string)$response->json('reference');if($reference==='')throw new DomainException('Provider response did not include a reference.');return new ProviderInitiationResult($reference,'PENDING_CUSTOMER',['http_status'=>$response->status(),'request_id'=>$r]);}}
